63	    // MARK: - Suggestions bar
64	
65	    private var currentWord: String {
66	        // Get the last word being typed (after last space or newline)
67	        let trimmed = text.replacingOccurrences(of: "\n", with: " ")
68	        return trimmed.split(separator: " ").last.map(String.init) ?? ""
69	    }
70	
71	    private var commandSuggestionsBar: some View {
72	        ScrollView(.horizontal, showsIndicators: false) {
73	            HStack(spacing: 8) {
74	                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
75	                    Button {
76	                        insertSuggestion(cmd)
77	                    } label: {
78	                        Text(cmd)
79	                            .font(.system(size: 13, weight: .medium, design: .monospaced))
80	                            .foregroundStyle(.white.opacity(0.85))
81	                            .padding(.horizontal, 12)
82	                            .padding(.vertical, 6)
83	                            .background(
84	                                RoundedRectangle(cornerRadius: 8)
85	                                    .fill(.white.opacity(0.1))
86	                            )
87	                    }
88	                }
89	            }
90	            .padding(.horizontal, 16)
91	        }
92	        .frame(height: 36)
93	    }
94	
95	    private func insertSuggestion(_ command: String) {
96	        // Replace the current word with the suggestion
97	        let parts = text.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
98	        if parts.isEmpty {
99	            text = command + " "
100	        } else {
101	            var updated = parts
102	            updated[updated.count - 1] = command
103	            text = updated.joined(separator: " ") + " "
104	        }
105	    }
106	
107	    private func learnCommand(_ input: String) {
108	        // Learn the first word of what was sent (the command)
109	        let firstWord = input.trimmingCharacters(in: .whitespacesAndNewlines)
110	            .split(separator: " ").first.map(String.init) ?? ""
111	        if !firstWord.isEmpty {
112	            commandDict.add(firstWord)
113	        }
114	    }
115	}
