223	// MARK: - URLSessionWebSocketDelegate
224	
225	extension BridgeClient: URLSessionWebSocketDelegate {
226	    func urlSession(
227	        _ session: URLSession,
228	        webSocketTask: URLSessionWebSocketTask,
229	        didOpenWithProtocol protocol: String?
230	    ) {
231	        backoff = 1
232	        useTailscale = false // Reset — LAN worked, prefer it next time
233	        Task { @MainActor in
234	            self.delegate?.clientDidConnect(self)
235	        }
236	    }
237	
238	    func urlSession(
239	        _ session: URLSession,
240	        webSocketTask: URLSessionWebSocketTask,
241	        didCloseWith closeCode: URLSessionWebSocketTask.CloseCode,
242	        reason: Data?
243	    ) {
244	        handleDisconnect(error: nil)
245	    }
246	}
