393	+
394	+    // Suggestions + control keys merged into a single scrollable row so the
395	+    // whole bar is just this row + the compose row when the keyboard is up.
396	+    private var compactChipsRow: some View {
397	+        ScrollView(.horizontal, showsIndicators: false) {
398	+            HStack(spacing: 6) {
