411	+    private func suggestionChip(_ cmd: String) -> some View {
412	+        Button {
413	+            insertSuggestion(cmd)
414	+        } label: {
415	+            Text(cmd)
416	+                .font(.system(size: 12, weight: .medium, design: .monospaced))
417	+                .foregroundStyle(.white.opacity(0.85))
418	+                .padding(.horizontal, 10)
419	+                .padding(.vertical, 5)
420	+                .background(Capsule().fill(.white.opacity(0.1)))
421	+        }
422	+    }
423	+
424	+    private func controlChip(label: String, key: String) -> some View {
425	+        Button {
