427	+        } label: {
428	+            Text(label)
429	+                .font(.system(size: 13, weight: .medium, design: .monospaced))
430	+                .foregroundStyle(.white.opacity(0.75))
431	+                .frame(minWidth: 34)
432	+                .padding(.vertical, 6)
433	+                .background(RoundedRectangle(cornerRadius: 7).fill(.white.opacity(0.08)))
434	+        }
435	+    }
436	+
437	+    // MARK: - Actions
438	+
439	+    private func send(withEnter: Bool) {
440	+        let text = draft
441	+        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
442	+        learnCommand(text)
443	+        if withEnter {
444	+            onSendEnter(text)
445	+        } else {
446	+            onSendText(text)
447	+        }
448	+        draft = ""
449	+        // Keep the keyboard up so the user can fire off several commands.
450	+    }
451	+
452	+    private func insertSuggestion(_ command: String) {
453	+        let parts = draft.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
454	+        if parts.isEmpty {
455	+            draft = command + " "
456	+        } else {
457	+            var updated = parts
458	+            updated[updated.count - 1] = command
459	+            draft = updated.joined(separator: " ") + " "
460	+        }
461	+    }
462	+
463	+    private func learnCommand(_ input: String) {
464	+        let firstWord = input.trimmingCharacters(in: .whitespacesAndNewlines)
465	+            .split(separator: " ").first.map(String.init) ?? ""
466	+        if !firstWord.isEmpty { commandDict.add(firstWord) }
467	+    }
468	+}
