592	+++ b/ios/cmux/Layout/TerminalTextView.swift
593	@@ -0,0 +1,83 @@
594	+import SwiftUI
595	+import UIKit
596	+
597	+/// A UITextView-backed terminal renderer that supports text selection (copy)
598	+/// and tappable links via data detectors — neither of which SwiftUI's `Text`
599	+/// can do. It scrolls itself and keeps pinned to the bottom for live output,
600	+/// but yields to the user the moment they scroll up or start a selection.
601	+struct TerminalTextView: UIViewRepresentable {
602	+    let text: String
603	+    let fontSize: CGFloat
604	+    let textOpacity: Double
605	+
606	+    func makeCoordinator() -> Coordinator { Coordinator() }
607	+
608	+    func makeUIView(context: Context) -> UITextView {
609	+        let tv = UITextView()
610	+        tv.isEditable = false
611	+        tv.isSelectable = true
612	+        tv.isScrollEnabled = true
613	+        tv.dataDetectorTypes = [.link]          // linkify URLs in the output
614	+        tv.backgroundColor = .clear
615	+        tv.textContainerInset = UIEdgeInsets(top: 6, left: 8, bottom: 6, right: 8)
616	+        tv.textContainer.lineFragmentPadding = 0
617	+        tv.showsVerticalScrollIndicator = false
618	+        tv.alwaysBounceVertical = true
619	+        tv.delegate = context.coordinator
620	+        // Terminal output is not natural language — don't fight the user with it.
621	+        tv.autocorrectionType = .no
622	+        tv.autocapitalizationType = .none
623	+        tv.attributedText = attributed()
624	+        return tv
625	+    }
626	+
627	+    func updateUIView(_ tv: UITextView, context: Context) {
628	+        // Don't clobber an in-progress selection (a live poll would otherwise
629	+        // yank the text out from under the user mid-copy).
630	+        if tv.selectedRange.length > 0 { return }
631	+
632	+        let newAttr = attributed()
633	+        if tv.attributedText != newAttr {
634	+            tv.attributedText = newAttr
635	+            if context.coordinator.autoScroll {
636	+                scrollToBottom(tv)
637	+            }
638	+        }
639	+    }
640	+
641	+    private func attributed() -> NSAttributedString {
642	+        let style = NSMutableParagraphStyle()
643	+        style.lineSpacing = 1
644	+        return NSAttributedString(
645	+            string: text,
646	+            attributes: [
647	+                .font: UIFont.monospacedSystemFont(ofSize: fontSize, weight: .regular),
648	+                .foregroundColor: UIColor.white.withAlphaComponent(textOpacity),
649	+                .paragraphStyle: style,
650	+            ]
651	+        )
652	+    }
653	+
654	+    private func scrollToBottom(_ tv: UITextView) {
655	+        // Defer a runloop so layout reflects the new content size first.
656	+        DispatchQueue.main.async {
657	+            let bottom = max(0, tv.contentSize.height - tv.bounds.height + tv.adjustedContentInset.bottom)
658	+            if bottom > 0 {
659	+                tv.setContentOffset(CGPoint(x: 0, y: bottom), animated: false)
660	+            }
661	+        }
662	+    }
663	+
664	+    final class Coordinator: NSObject, UITextViewDelegate {
665	+        /// Whether new output should keep the view pinned to the bottom.
666	+        /// True while the user is at (or near) the bottom; false once they
667	+        /// scroll up to read scrollback.
668	+        var autoScroll = true
669	+
670	+        func scrollViewDidScroll(_ scrollView: UIScrollView) {
671	+            let threshold: CGFloat = 24
672	+            let maxOffset = scrollView.contentSize.height - scrollView.bounds.height
673	+            autoScroll = scrollView.contentOffset.y >= maxOffset - threshold
674	+        }
675	+    }
676	+}
